import xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
for f in ['xl/worksheets/sheet1.xml','xl/worksheets/sheet2.xml']:
    print('====',f)
    tree=ET.parse(f)
    root=tree.getroot()
    for row in root.findall('.//m:sheetData/m:row',ns):
        r=row.get('r')
        cells=[]
        for c in row.findall('m:c',ns):
            ref=c.get('r'); s=c.get('s'); t=c.get('t')
            v=c.find('m:v',ns); is_=c.find('m:is',ns); f_=c.find('m:f',ns)
            val=None
            if v is not None: val=v.text
            if is_ is not None: val=''.join(is_.itertext())
            if f_ is not None: val='FORMULA:'+ (f_.text or '')
            cells.append((ref,s,t,val))
        print(r, cells)
